INSERT INTO email_templates (id, event_code, event_name, category, subject, body_html, available_variables, is_active, updated_by_user_id, created_at, updated_at) VALUES (1, 'ADMIN_NEW_USER_ALERT', 'Pemberitahuan Pendaftar Baru', 'Auth', 'Pendaftaran Baru Memerlukan Persetujuan - {UserFullName}', '<h3>Pendaftaran Pengguna Baru</h3><p>Pengguna baru <strong>{UserFullName}</strong> ({UserEmail}) telah mendaftar dengan kode perusahaan <strong>{CompanyCode}</strong> dan menunggu persetujuan Anda.</p>', '{UserFullName},{UserEmail},{CompanyCode},{RegisterDate}', TRUE, NULL, '2026-11-05T07:06:51.5470310+00:00', '2026-11-05T07:06:51.5470310+00:00') ON CONFLICT (id) DO UPDATE SET event_code = EXCLUDED.event_code, event_name = EXCLUDED.event_name, category = EXCLUDED.category, subject = EXCLUDED.subject, body_html = EXCLUDED.body_html, available_variables = EXCLUDED.available_variables, is_active = EXCLUDED.is_active, updated_by_user_id = EXCLUDED.updated_by_user_id, created_at = EXCLUDED.created_at, updated_at = EXCLUDED.updated_at;
INSERT INTO email_templates (id, event_code, event_name, category, subject, body_html, available_variables, is_active, updated_by_user_id, created_at, updated_at) VALUES (2, 'USER_APPROVED', 'Akun Disetujui', 'Auth', 'Selamat! Akun TrackerKerja Anda Telah Disetujui', '<h3>Akun Anda Aktif!</h3><p>Halo {UserFullName}, pendaftaran Anda di <strong>{CompanyName}</strong> telah disetujui. Anda dapat masuk ke aplikasi sekarang.</p>', '{UserFullName},{CompanyName},{LoginUrl}', TRUE, NULL, '2026-11-05T07:06:51.5470310+00:00', '2026-11-05T07:06:51.5470310+00:00') ON CONFLICT (id) DO UPDATE SET event_code = EXCLUDED.event_code, event_name = EXCLUDED.event_name, category = EXCLUDED.category, subject = EXCLUDED.subject, body_html = EXCLUDED.body_html, available_variables = EXCLUDED.available_variables, is_active = EXCLUDED.is_active, updated_by_user_id = EXCLUDED.updated_by_user_id, created_at = EXCLUDED.created_at, updated_at = EXCLUDED.updated_at;
INSERT INTO email_templates (id, event_code, event_name, category, subject, body_html, available_variables, is_active, updated_by_user_id, created_at, updated_at) VALUES (3, 'PASSWORD_RESET', 'Permintaan Reset Kata Sandi', 'Security', 'Instruksi Pengaturan Ulang Kata Sandi TrackerKerja', '<h3>Reset Kata Sandi</h3><p>Klik tautan berikut untuk mereset kata sandi Anda: <a href="{ResetUrl}">Reset Password</a>. Tautan berlaku 15 menit.</p>', '{UserFullName},{ResetUrl},{TokenLifespan}', TRUE, NULL, '2026-11-05T07:06:51.5470310+00:00', '2026-11-05T07:06:51.5470310+00:00') ON CONFLICT (id) DO UPDATE SET event_code = EXCLUDED.event_code, event_name = EXCLUDED.event_name, category = EXCLUDED.category, subject = EXCLUDED.subject, body_html = EXCLUDED.body_html, available_variables = EXCLUDED.available_variables, is_active = EXCLUDED.is_active, updated_by_user_id = EXCLUDED.updated_by_user_id, created_at = EXCLUDED.created_at, updated_at = EXCLUDED.updated_at;
