INSERT INTO tasks (id, title, description, priority, status, progress, milestone, obstacle, solution, tags, project_id, category_id, assigned_to_user_id, parent_task_id, company_id, start_date, due_date, created_at, updated_at) VALUES (944, 'Implementasi Engine Penyimpanan File Fisik Lokal, Penyesuaian Batas Payload, dan Proxy Preview Berkas di TICS v2.', 'Implementasi Engine Penyimpanan File Fisik Lokal, Penyesuaian Batas Payload, dan Proxy Preview Berkas di TICS v2.', 1, 2, 100, 'ENHANCEMENT', 'Service backend belum memiliki mekanisme penyimpanan fisik untuk berkas tanda tangan, paraf, dan lampiran uploader sehingga memicu error HTTP 413 Request Entity Too Large dan ketiadaan fitur preview dokumen.', 'Membangun engine utilitas local storage untuk penyimpanan file terstruktur di root /storage/, menaikkan batas body parser ke 10MB di seluruh service, serta mengonfigurasi ServeStaticModule dan proxy Vite untuk file preview langsung.', 'import:excel', 32, NULL, 'usr-526a154e', NULL, 3, '2026-08-26T00:00:00.0000000+00:00', '2026-08-28T00:00:00.0000000+00:00', '2026-11-05T07:32:03.7160750+00:00', '2026-11-05T07:32:03.7160750+00:00') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, priority = EXCLUDED.priority, status = EXCLUDED.status, progress = EXCLUDED.progress, milestone = EXCLUDED.milestone, obstacle = EXCLUDED.obstacle, solution = EXCLUDED.solution, tags = EXCLUDED.tags, project_id = EXCLUDED.project_id, category_id = EXCLUDED.category_id, assigned_to_user_id = EXCLUDED.assigned_to_user_id, parent_task_id = EXCLUDED.parent_task_id, company_id = EXCLUDED.company_id, start_date = EXCLUDED.start_date, due_date = EXCLUDED.due_date, created_at = EXCLUDED.created_at, updated_at = EXCLUDED.updated_at;
INSERT INTO tasks (id, title, description, priority, status, progress, milestone, obstacle, solution, tags, project_id, category_id, assigned_to_user_id, parent_task_id, company_id, start_date, due_date, created_at, updated_at) VALUES (945, 'Refactor dan Optimasi Create Transaction DOTS dengan Asynchronous SharePoint Queue.', 'Refactor dan Optimasi Create Transaction DOTS dengan Asynchronous SharePoint Queue.', 2, 2, 100, 'ENHANCEMENT', 'Submit transaksi menghasilkan HTTP 500 setelah database commit karena job kosong, schema queue belum lengkap, metadata tanggal tidak valid, serta retry berhenti sebelum provisioning SharePoint selesai.', 'Implementasikan encrypted queue job yang idempotent, migration dan status provisioning, app-only token, locking nomor DOTS, retry terstruktur, logging aman, serta monitoring real-time worker dan SharePoint.', 'import:excel', 29, NULL, 'usr-526a154e', NULL, 3, '2026-08-31T00:00:00.0000000+00:00', '2026-08-31T00:00:00.0000000+00:00', '2026-11-05T07:32:03.7160990+00:00', '2026-11-05T07:32:03.7160990+00:00') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, priority = EXCLUDED.priority, status = EXCLUDED.status, progress = EXCLUDED.progress, milestone = EXCLUDED.milestone, obstacle = EXCLUDED.obstacle, solution = EXCLUDED.solution, tags = EXCLUDED.tags, project_id = EXCLUDED.project_id, category_id = EXCLUDED.category_id, assigned_to_user_id = EXCLUDED.assigned_to_user_id, parent_task_id = EXCLUDED.parent_task_id, company_id = EXCLUDED.company_id, start_date = EXCLUDED.start_date, due_date = EXCLUDED.due_date, created_at = EXCLUDED.created_at, updated_at = EXCLUDED.updated_at;
