INSERT INTO tasks (id, title, description, priority, status, progress, milestone, obstacle, solution, tags, project_id, category_id, assigned_to_user_id, parent_task_id, company_id, start_date, due_date, created_at, updated_at) VALUES (948, 'Refactor lanjutan terkait pengurangan god object dan setup aturan job worker pada api-dots', 'Refactor lanjutan terkait pengurangan god object dan setup aturan job worker pada api-dots', 1, 2, 100, 'ENHANCEMENT', 'Banyak sekali god object (satu file sangat panjang yang berisi logic dan komponen terpusat) pada project api-dots sehingga menyulitkan fase maintenance dan tracing code. Serta pada api-dots production berlum diimplementasikan background job worker untuk dapat menampung logic optimasi request create dots transaction', 'Mengurangi god object dengan memisahkan komponen-komponen dan logic reusable menjadi file yang lebih kecil, serta membuat file cara setup background job yang diperlukan pada api-dots production', 'import:excel', 29, NULL, 'usr-526a154e', NULL, 3, '2026-09-03T00:00:00.0000000+00:00', '2026-09-03T00:00:00.0000000+00:00', '2026-11-05T07:32:03.7161570+00:00', '2026-11-05T07:32:03.7161570+00:00') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, priority = EXCLUDED.priority, status = EXCLUDED.status, progress = EXCLUDED.progress, milestone = EXCLUDED.milestone, obstacle = EXCLUDED.obstacle, solution = EXCLUDED.solution, tags = EXCLUDED.tags, project_id = EXCLUDED.project_id, category_id = EXCLUDED.category_id, assigned_to_user_id = EXCLUDED.assigned_to_user_id, parent_task_id = EXCLUDED.parent_task_id, company_id = EXCLUDED.company_id, start_date = EXCLUDED.start_date, due_date = EXCLUDED.due_date, created_at = EXCLUDED.created_at, updated_at = EXCLUDED.updated_at;
