INSERT INTO tasks (id, title, description, priority, status, progress, milestone, obstacle, solution, tags, project_id, category_id, assigned_to_user_id, parent_task_id, company_id, start_date, due_date, created_at, updated_at) VALUES (950, 'Implementasi Focus-Based Collaborative Row Lock dan Release Cooldown pada Modul Cash & Bank serta meeting progress bersama tim ERP TUGU', 'Implementasi Focus-Based Collaborative Row Lock dan Release Cooldown pada Modul Cash & Bank serta meeting progress bersama tim ERP TUGU', 2, 2, 100, 'ENHANCEMENT', 'Penguncian baris sebelumnya hanya aktif saat user mengetik dan hanya di input itu saja (bukan 1 rows) sehingga rawan terjadi tabrakan input ketika kursor sudah berada di dalam sel, serta ketiadaan jeda transisi saat user berpindah baris.', 'Mengaktifkan penguncian seluruh baris seketika saat kursor masuk input (onFocus), mempercepat sinkronisasi heartbeat ke 2,5 detik, serta menerapkan jeda cooldown 300ms dengan indikator gembok berdenyut saat baris ditinggalkan.', 'import:excel', 29, NULL, 'usr-526a154e', NULL, 3, '2026-09-04T00:00:00.0000000+00:00', '2026-09-07T00:00:00.0000000+00:00', '2026-11-05T07:32:03.7162050+00:00', '2026-11-05T07:32:03.7162050+00:00') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, priority = EXCLUDED.priority, status = EXCLUDED.status, progress = EXCLUDED.progress, milestone = EXCLUDED.milestone, obstacle = EXCLUDED.obstacle, solution = EXCLUDED.solution, tags = EXCLUDED.tags, project_id = EXCLUDED.project_id, category_id = EXCLUDED.category_id, assigned_to_user_id = EXCLUDED.assigned_to_user_id, parent_task_id = EXCLUDED.parent_task_id, company_id = EXCLUDED.company_id, start_date = EXCLUDED.start_date, due_date = EXCLUDED.due_date, created_at = EXCLUDED.created_at, updated_at = EXCLUDED.updated_at;
INSERT INTO tasks (id, title, description, priority, status, progress, milestone, obstacle, solution, tags, project_id, category_id, assigned_to_user_id, parent_task_id, company_id, start_date, due_date, created_at, updated_at) VALUES (951, 'Implementasi Range Selection & Multi-Row Copy ke SAP serta Refaktorisasi Cell Applicability pada Cash & Bank Grid', 'Implementasi Range Selection & Multi-Row Copy ke SAP serta Refaktorisasi Cell Applicability pada Cash & Bank Grid', 2, 2, 100, 'ENHANCEMENT', 'Tim Cash & Bank masih bergantung pada spreadsheet manual karena tabel DOTS belum mendukung blok multi-baris untuk disalin massal ke SAP, serta logika penonaktifan sel sebelumnya masih rapuh dan tercampur di komponen UI.', 'Dibuat custom hook useGridRangeSelection untuk fitur drag-to-select dan batch copy format SAP (Ctrl+C), tombol salin 1-klik pada header kolom rujukan, serta pemisahan logika fase transaksi ke pure function isColumnApplicable yang selaras dengan aturan backend.', 'import:excel', 29, NULL, 'usr-526a154e', NULL, 3, '2026-09-04T00:00:00.0000000+00:00', '2026-09-09T00:00:00.0000000+00:00', '2026-11-05T07:32:03.7162290+00:00', '2026-11-05T07:32:03.7162290+00:00') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, priority = EXCLUDED.priority, status = EXCLUDED.status, progress = EXCLUDED.progress, milestone = EXCLUDED.milestone, obstacle = EXCLUDED.obstacle, solution = EXCLUDED.solution, tags = EXCLUDED.tags, project_id = EXCLUDED.project_id, category_id = EXCLUDED.category_id, assigned_to_user_id = EXCLUDED.assigned_to_user_id, parent_task_id = EXCLUDED.parent_task_id, company_id = EXCLUDED.company_id, start_date = EXCLUDED.start_date, due_date = EXCLUDED.due_date, created_at = EXCLUDED.created_at, updated_at = EXCLUDED.updated_at;
