INSERT INTO tasks (id, title, description, priority, status, progress, milestone, obstacle, solution, tags, project_id, category_id, assigned_to_user_id, parent_task_id, company_id, start_date, due_date, created_at, updated_at) VALUES (955, 'Audit Prosedur Enforce Polis Database dan Analisis Arsitektur Refactoring.', 'Audit Prosedur Enforce Polis Database dan Analisis Arsitektur Refactoring.', 0, 2, 100, 'MAINTENANCE', 'Diperlukan pembedahan mendalam terhadap logika stored procedure enforce (80.000+ karakter) serta evaluasi risiko performa/timeout jika dipindahkan ke level kode atau microservice.', 'Berhasil memetakan 5 tahapan validasi SP enforce via PostgreSQL MCP, menganalisis mitigasi risiko timeout, serta merumuskan rekomendasi arsitektur Modular Domain Service (Pipeline Pattern).', 'import:excel', 33, NULL, 'usr-526a154e', NULL, 3, '2026-09-14T00:00:00.0000000+00:00', '2026-09-14T00:00:00.0000000+00:00', '2026-11-05T07:32:03.7209420+00:00', '2026-11-05T07:32:03.7209420+00:00') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, priority = EXCLUDED.priority, status = EXCLUDED.status, progress = EXCLUDED.progress, milestone = EXCLUDED.milestone, obstacle = EXCLUDED.obstacle, solution = EXCLUDED.solution, tags = EXCLUDED.tags, project_id = EXCLUDED.project_id, category_id = EXCLUDED.category_id, assigned_to_user_id = EXCLUDED.assigned_to_user_id, parent_task_id = EXCLUDED.parent_task_id, company_id = EXCLUDED.company_id, start_date = EXCLUDED.start_date, due_date = EXCLUDED.due_date, created_at = EXCLUDED.created_at, updated_at = EXCLUDED.updated_at;
INSERT INTO tasks (id, title, description, priority, status, progress, milestone, obstacle, solution, tags, project_id, category_id, assigned_to_user_id, parent_task_id, company_id, start_date, due_date, created_at, updated_at) VALUES (956, 'UI Improvement pada halaman home tics retail mass product', 'UI Improvement pada halaman home tics retail mass product', 1, 2, 100, 'ENHANCEMENT', 'Dari sisi tampilan tics retail perlu dibedakan dengan tics lainnya, agar user mengetahui sedang berada di tics retail non-mv, kemudian juga dibutuhkan improvement untuk ui nya agar mempunyai tampilan yang lebih modern dan enak dilihat', 'Melakukan improvement pada tampilan tics retail, terutama halaman home sebagai halaman pertama kali user visit, menamabahkan label tics retail non-mv pada halaman tsb agar user mengetahui sedang akses webnya tics retail non-mv (bukan tics yang lain)', 'import:excel', 33, NULL, 'usr-526a154e', NULL, 3, '2026-09-15T00:00:00.0000000+00:00', '2026-09-15T00:00:00.0000000+00:00', '2026-11-05T07:32:03.7209610+00:00', '2026-11-05T07:32:03.7209620+00:00') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, priority = EXCLUDED.priority, status = EXCLUDED.status, progress = EXCLUDED.progress, milestone = EXCLUDED.milestone, obstacle = EXCLUDED.obstacle, solution = EXCLUDED.solution, tags = EXCLUDED.tags, project_id = EXCLUDED.project_id, category_id = EXCLUDED.category_id, assigned_to_user_id = EXCLUDED.assigned_to_user_id, parent_task_id = EXCLUDED.parent_task_id, company_id = EXCLUDED.company_id, start_date = EXCLUDED.start_date, due_date = EXCLUDED.due_date, created_at = EXCLUDED.created_at, updated_at = EXCLUDED.updated_at;
