INSERT INTO tasks (id, title, description, priority, status, progress, milestone, obstacle, solution, tags, project_id, category_id, assigned_to_user_id, parent_task_id, company_id, start_date, due_date, created_at, updated_at) VALUES (975, 'Proteksi Scheduler Retry SharePoint & Penanganan Transaksi Historis', 'Proteksi Scheduler Retry SharePoint & Penanganan Transaksi Historis', 1, 2, 100, 'BUG', 'Penambahan kolom status dengan default pending menyebabkan belasan ribu transaksi historis lama dan transaksi yang sudah ditolak/batal (3010/3020) ikut masuk ke dalam antrean retry scheduler, sehingga memicu pemborosan trafik Graph API dan risiko infinite retry loop.', 'Menjalankan migrasi idempoten untuk menandai transaksi lawas tanpa folder menjadi legacy, serta memperkuat query command scheduler dengan mengecualikan status gugur/batal (3010/3020) dan membatasi rentang usia transaksi yang diproses maksimal 30 hari ke belakang (--max-age-days=30).', 'import:excel', 29, NULL, 'usr-526a154e', NULL, 3, '2026-10-15T00:00:00.0000000+00:00', '2026-10-15T00:00:00.0000000+00:00', '2026-11-05T07:32:03.7308890+00:00', '2026-11-05T07:32:03.7308890+00:00') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, priority = EXCLUDED.priority, status = EXCLUDED.status, progress = EXCLUDED.progress, milestone = EXCLUDED.milestone, obstacle = EXCLUDED.obstacle, solution = EXCLUDED.solution, tags = EXCLUDED.tags, project_id = EXCLUDED.project_id, category_id = EXCLUDED.category_id, assigned_to_user_id = EXCLUDED.assigned_to_user_id, parent_task_id = EXCLUDED.parent_task_id, company_id = EXCLUDED.company_id, start_date = EXCLUDED.start_date, due_date = EXCLUDED.due_date, created_at = EXCLUDED.created_at, updated_at = EXCLUDED.updated_at;
INSERT INTO tasks (id, title, description, priority, status, progress, milestone, obstacle, solution, tags, project_id, category_id, assigned_to_user_id, parent_task_id, company_id, start_date, due_date, created_at, updated_at) VALUES (976, 'Refactoring Polimorfisme Output Dokumen & Rincian Suku Premi Fire', 'Refactoring Polimorfisme Output Dokumen & Rincian Suku Premi Fire', 1, 2, 100, 'ENHANCEMENT', 'Dokumen service sebelumnya monolitik dan mencampurkan logika spesifik Fire ke base class, mengakibatkan suku premi pada polis multi-objek terakumulasi secara otomatis dan tidak bisa dirinci per objek dalam format tabel.', 'Memecah base class ke dalam 5 domain trait modular, memindahkan seluruh logika Fire ke FireDocumentService, serta menyajikan suku premi dalam tabel 2 kolom yang presisi (tarif tunggal jika seragam, atau dirinci per objek jika berbeda).', 'import:excel', 35, NULL, 'usr-526a154e', NULL, 3, '2026-10-16T00:00:00.0000000+00:00', '2026-10-16T00:00:00.0000000+00:00', '2026-11-05T07:32:03.7309090+00:00', '2026-11-05T07:32:03.7309090+00:00') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, priority = EXCLUDED.priority, status = EXCLUDED.status, progress = EXCLUDED.progress, milestone = EXCLUDED.milestone, obstacle = EXCLUDED.obstacle, solution = EXCLUDED.solution, tags = EXCLUDED.tags, project_id = EXCLUDED.project_id, category_id = EXCLUDED.category_id, assigned_to_user_id = EXCLUDED.assigned_to_user_id, parent_task_id = EXCLUDED.parent_task_id, company_id = EXCLUDED.company_id, start_date = EXCLUDED.start_date, due_date = EXCLUDED.due_date, created_at = EXCLUDED.created_at, updated_at = EXCLUDED.updated_at;
INSERT INTO tasks (id, title, description, priority, status, progress, milestone, obstacle, solution, tags, project_id, category_id, assigned_to_user_id, parent_task_id, company_id, start_date, due_date, created_at, updated_at) VALUES (977, 'Resolusi Konflik Merge UAT, Preservasi Fitur Marine, & Label Objek Fire', 'Resolusi Konflik Merge UAT, Preservasi Fitur Marine, & Label Objek Fire', 1, 2, 100, 'ENHANCEMENT', 'Merge dari branch uat menimbulkan konflik Git pada BaseDocumentService yang berisiko menghilangkan fitur running number klausul Marine Cargo, serta label baris suku premi Fire multi-objek belum memuat indeks pembeda antar objek.', 'Menyelesaikan konflik dengan mempertahankan base service tetap modular, mempreservasi logika Marine Cargo ke dalam trait terkait, memperbaiki penamaan label menjadi (Objek N), dan memastikan seluruh 40 skenario pengujian lulus 100%.', 'import:excel', 35, NULL, 'usr-526a154e', NULL, 3, '2026-10-19T00:00:00.0000000+00:00', '2026-10-19T00:00:00.0000000+00:00', '2026-11-05T07:32:03.7309270+00:00', '2026-11-05T07:32:03.7309270+00:00') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, priority = EXCLUDED.priority, status = EXCLUDED.status, progress = EXCLUDED.progress, milestone = EXCLUDED.milestone, obstacle = EXCLUDED.obstacle, solution = EXCLUDED.solution, tags = EXCLUDED.tags, project_id = EXCLUDED.project_id, category_id = EXCLUDED.category_id, assigned_to_user_id = EXCLUDED.assigned_to_user_id, parent_task_id = EXCLUDED.parent_task_id, company_id = EXCLUDED.company_id, start_date = EXCLUDED.start_date, due_date = EXCLUDED.due_date, created_at = EXCLUDED.created_at, updated_at = EXCLUDED.updated_at;
