INSERT INTO tasks (id, title, description, priority, status, progress, milestone, obstacle, solution, tags, project_id, category_id, assigned_to_user_id, parent_task_id, company_id, start_date, due_date, created_at, updated_at) VALUES (1020, 'Fixing PostgreSQL integration and Laravel controllers, refining the Next.js Queue and Reports & Analytics UI, and solidifying the overall ITSM workflow logic.', 'Fixing PostgreSQL integration and Laravel controllers, refining the Next.js Queue and Reports & Analytics UI, and solidifying the overall ITSM workflow logic.', 1, 2, 100, NULL, 'error 404 dan 500 pada API akibat kesalahan rute serta nama controller di backend Laravel, angka metrik dasbor Reports & Analytics yang menampilkan nilai 0 karena ketidaksesuaian struktur JSON dan query tanggal, antarmuka modul Queue serta Reports yang belum sesuai dengan standar desain Clean Modern Enterprise, kendala pemetaan peran dalam penyaringan Assignee tiket, serta masalah integrasi koneksi multi-database dengan PostgreSQL', 'mendaftarkan ulang rute API dan memperbaiki penamaan controller, menyesuaikan struktur respons JSON serta menambahkan rentang jam pada klausa query tanggal di Laravel, memperbarui tampilan frontend menggunakan Material UI berorientasi warna soft blue dan tipografi Inter, memfilter dropdown Assignee khusus untuk pengguna berperan technician, serta mengaktifkan ekstensi PHP yang dibutuhkan dan mengonfigurasi charset PostgreSQL', 'import:excel', 37, NULL, 'usr-b6432a53', NULL, 3, '2026-09-17T00:00:00.0000000+00:00', '2026-09-17T00:00:00.0000000+00:00', '2026-11-05T07:32:03.9324600+00:00', '2026-11-05T07:32:03.9324600+00:00') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, priority = EXCLUDED.priority, status = EXCLUDED.status, progress = EXCLUDED.progress, milestone = EXCLUDED.milestone, obstacle = EXCLUDED.obstacle, solution = EXCLUDED.solution, tags = EXCLUDED.tags, project_id = EXCLUDED.project_id, category_id = EXCLUDED.