INSERT INTO tasks (id, title, description, priority, status, progress, milestone, obstacle, solution, tags, project_id, category_id, assigned_to_user_id, parent_task_id, company_id, start_date, due_date, created_at, updated_at) VALUES (1046, 'Fixing temuan critical (flow tts)', 'Fixing temuan critical (flow tts)', 2, 2, 100, NULL, 'peran Share Services yang tidak memiliki izin untuk menugaskan (assign) tiket ke teknisi, teknisi yang sudah ditugaskan tidak dapat memperbarui status tiketnya secara mandiri karena keterbatasan otorisasi dan ketiadaan antarmuka aksi status, belum adanya pembatasan visibilitas data tiket yang aman antar-peran (Requester dan Teknisi), proses logout di lingkungan lokal yang selalu berulang otomatis masuk ke akun Super Admin akibat cookie JWT yang tidak terhapus', 'menambahkan hak akses penugasan tiket untuk Share Services melalui pembaruan konfigurasi dan migrasi database, memberikan otorisasi kelola kepada teknisi yang ditugaskan disertai penambahan dropdown status dan tombol aksi cepat (Start Progress, Put On Hold, Resolve) pada antarmuka tiket, memperketat query scoping agar Requester hanya melihat tiket buatannya dan Teknisi hanya melihat tiket yang ditugaskan kepadanya, memperbaiki mekanisme logout lokal dengan menghapus cookie JWT serta menyiapkan pemilih 3 peran uji yang selaras dengan skema database UAT', 'import:excel', 25, NULL, 'usr-b6432a53', NULL, 3, '2026-10-28T00:00:00.0000000+00:00', '2026-10-29T00:00:00.0000000+00:00', '2026-11-05T07:32:03.9410340+00:00', '2026-11-05T07:32:03.9410340+00:00') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, priority = EXCLUDED.priority, status = EXCLUDED.status, progress = EXCLUDED.progress, milestone = EXCLUDED.milestone, obstacle = EXCLUDED.obstacle, solution = EXCLUDED.solution, tags = EXCLUDED.tags, project_id = EXCLUDED.project_id, category_id = EXCLUDED.category_id, assigned_to_user_id = EXCLUDED.assigned_to_user_id, parent_task_id = EXCLUDED.p